/* @lc app=leetcode id=3635 lang=kotlin */ class Solution { fun earliestFinishTime(landStartTime: IntArray, landDuration: IntArray, waterStartTime: IntArray, waterDuration: IntArray): Int = minOf(landStartTime.indices.minOf { landStartTime[it] + landDuration[it] }.let { e -> waterStartTime.indices.minOf { maxOf(e, waterStartTime[it]) + waterDuration[it] } }, waterStartTime.indices.minOf { waterStartTime[it] + waterDuration[it] }.let { e -> landStartTime.indices.minOf { maxOf(e, landStartTime[it]) + landDuration[it] } }) }